{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Thalidomide, a neutral, poorly soluble but well-absorbed drug, has an absolute oral bioavailability of 80–100% at low doses in fasting healthy volunteers, supporting high F for a neutral rigid molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Hexobarbital, a lipophilic neutral barbiturate, has an absolute oral bioavailability of 90% in humans, showing that high lipophilicity and lack of ionizable groups do not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ursodeoxycholic acid, a steroid-like molecule, showed 50% systemic availability in normal subjects after oral versus IV administration, still well above the 20% threshold and supportive for a steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Vildagliptin has an absolute oral bioavailability of approximately 85% in healthy volunteers, providing additional high-transfer evidence that well-absorbed oral drugs commonly exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Pentazocine had an absolute oral bioavailability of 18% in healthy subjects, below the threshold, but its phenolic and basic amine groups confer first-pass conjugation and metabolism liabilities that are absent in the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a rigid, lipophilic, neutral steroid-like lactone. High-transfer experimental evidence from multiple relevant drugs—thalidomide, hexobarbital, UDCA, vildagliptin, and others—shows oral bioavailability at or above 50–100%, strongly supporting high F. The only low-F analogue, pentazocine, has metabolic liabilities not present in the query. Therefore, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "No experimental data on lactone stability or first-pass hydrolysis for this specific scaffold.",
    "Solubility and dissolution behavior are inferred from physicochemical properties rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

